B=[['希腊 baptein → baptizein','浸入、蘸入；后来用于施洗']]
N=B+[['希腊 baptismos → 教会拉丁 baptismus','浸洗；洗礼'],['古法语 baptesme / bapteme → 英语 baptism','基督教的洗礼仪式']]
V=B+[['教会拉丁 baptizare → 古法语 baptiser / batisier','施行洗礼'],['中古英语 baptisen / baptizen → 英语 baptize','为……施洗']]
W=[
E('baptism','/ˈbæptɪzəm/','洗礼；初次经历某种考验','用水标记宗教生活中的一个重要开始；比喻用法则把第一次受考验也看成一种入门。','经古法语及教会拉丁语，来自希腊 baptismos，关联 baptizein 浸入、施洗。名词有自己的借入链，并不是英语 baptize 简单换后缀。',N,'基督教不同传统对洗礼对象、形式和意义的理解有所不同，有浸水、浇水等形式。baptism of fire 在现代非宗教语境常指初上阵就遇到严峻考验，未必真有火，也不必与宗教有关。','a baptism ceremony；receive baptism；a baptism of fire。','baptism 是洗礼；christening 常与洗礼、尤其婴儿洗礼及命名联系，但不能把所有传统中的 baptism 都简化为给婴儿取名。',('The family gathered at the church for the baptism.','家人聚在教堂参加洗礼。'),('Managing the crisis on her first day was a baptism of fire.','上班第一天就处理危机，对她来说是一次严峻的初次考验。'),sources=['https://www.etymonline.com/word/baptism','https://www.oxfordlearnersdictionaries.com/definition/english/baptism']),
E('baptize','/ˈbæptaɪz/','为……施洗；使受洗','baptism 是仪式，baptize 是施行这个仪式的动作。','经古法语 baptiser / batisier、教会拉丁 baptizare，来自希腊 baptizein 浸入、施洗。不能把它说成英语先有 baptism 才新造的动词。',V,'通常是施洗者 baptizes someone，受洗者 is baptized。这个被动形式很常见，因为叙述重点往往是某个人什么时候受洗。词源的浸入说明历史起点，现代不同宗派的具体仪式不完全相同。','baptize someone；be baptized；be baptized in a church。','baptize 是宗教施洗，wash 是一般清洗。它们都可能涉及水，但动作的社会和宗教意义不同。',('The minister baptized three new members during the service.','牧师在礼拜中为三位新成员施洗。'),('She was baptized in the village church.','她在村里的教堂受洗。'),sources=['https://www.etymonline.com/word/baptize','https://www.oxfordlearnersdictionaries.com/definition/english/baptize']),
E('baptise','/ˈbæptaɪz/','为……施洗；baptize 的常见英式拼写','看到 s 不用另记一种仪式：它和 baptize 是同一个动词的拼写变体。','与 baptize 共享希腊、拉丁、法语来源链；现代英语 -ise / -ize 拼写传统形成差别，baptise 尤常见于英式英语。',V+[['英式常用拼写 baptise','与 baptize 同义同音']],'过去式是 baptised，进行形式是 baptising。英式英语也会使用 baptize，特别是采用 -ize 拼写规范的出版物；因此不能简单断言带 z 就一定是美式。实际使用时跟随同一文档的拼写习惯即可。','baptise a child；be baptised；baptising new members。','baptise 与 baptize 没有意义差别；baptism 是名词，也不会因为采用 baptise 就改成另一种名词拼写。',('The parish records show that he was baptised there in infancy.','教区档案显示，他在婴儿时期曾在那里受洗。'),('The article uses the British spelling “baptise” throughout.','这篇文章始终采用英式拼写“baptise”。'),sources=['https://www.etymonline.com/word/baptise','https://www.oxfordlearnersdictionaries.com/definition/english/baptize']),
E('baptismal','/bæpˈtɪzməl/','洗礼的；与洗礼有关的','把洗礼仪式旁边的物品、记录和誓言都贴上同一张说明：这是用于洗礼或与洗礼相关的。','英语 baptism + -al 组成形容词；重音从 baptism 的开头移到中间。',N+[['英语 baptism + -al → baptismal','洗礼 → 与洗礼有关的']],'baptismal font 是盛洗礼用水的洗礼盆，baptismal record 是洗礼记录。它通常放在名词前作修饰语，不是说某个人已经受洗；“已受洗的”通常用 baptized。','a baptismal font；baptismal records；baptismal vows。','baptismal 说明与仪式有关，baptized 说明已接受仪式。baptismal water 是洗礼用水，不是受过洗礼的水。',('The stone baptismal font stands near the entrance to the church.','石制洗礼盆位于教堂入口附近。'),('She found her grandfather’s name in the baptismal records.','她在洗礼记录里找到了祖父的名字。'),sources=['https://www.etymonline.com/word/baptismal','https://www.oxfordlearnersdictionaries.com/definition/english/baptismal']),
E('Baptist','/ˈbæptɪst/','浸礼宗信徒；浸礼宗的；施洗者称号的一部分','这个名称把洗礼放在宗派身份的显眼位置；但不是所有实行洗礼的基督徒都叫 Baptist。','较早的施洗者义，经古法语 baptiste、教会拉丁及希腊 baptistes 而来；后来 Baptist 专用于浸礼宗成员。John the Baptist 里的称号保留的是施洗者这一较早含义。',B+[['教会希腊 baptistes → 拉丁、古法语 baptiste','施洗者'],['英语 baptist / Baptist','施洗者称号；后来特指浸礼宗信徒']],'现代 a Baptist 通常指浸礼宗信徒，Baptist church 指浸礼宗教会。这个传统强调在个人表达信仰后接受洗礼，通常采用浸水形式。John the Baptist 是施洗约翰，不能把这个古代人物称号理解成现代宗派的会员身份。','a Baptist church；Baptist congregations；John the Baptist。','baptized 只表示已经受洗，不说明宗派；Baptist 是更具体的宗派身份或历史称号。大小写和上下文都要一起看。',('Her family attends a Baptist church in the town centre.','她家在镇中心的一所浸礼宗教会参加礼拜。'),('The painting depicts John the Baptist beside a river.','这幅画描绘了河边的施洗约翰。'),sources=['https://www.etymonline.com/word/baptist','https://www.oxfordlearnersdictionaries.com/definition/english/baptist_2'])
]
ROOT=dict(id='C0111',meaning='浸入；蘸入；施洗',core='BAPT = DIP / IMMERSE',image='把东西浸入水里，发展成用水举行的宗教仪式；仪式所标记的开始，又能比喻初次经历考验。',intro='希腊 baptein 表示浸、蘸，baptizein 延伸出施洗含义。英语主要通过教会拉丁语和法语借入相关词。这个词根适合理解宗教、历史、艺术和 baptism of fire 这样的常见比喻。',forms='baptism 是仪式名词，baptize / baptise 是施行动词，baptismal 是相关形容词，Baptist 还涉及宗派名称。名词与动词各有历史借入路径，不按现代词尾反推唯一先后关系。',branches=[['仪式本身与比喻','baptism'],['施行或接受仪式','baptize、baptise'],['仪式有关的物品与记录','baptismal'],['施洗者称号与宗派','Baptist']],contrasts='词源上的浸入不等于所有现代教会采用同一种施洗方式；Baptist 也不等于任何受洗者。先分动作、仪式、相关形容词与宗派名，再看具体上下文。',practice='The baptismal record states when and where she was baptized.\n\n洗礼记录写明了她受洗的时间和地点。',words=[x['word'] for x in W],exclude={'abaptiston':'罕见历史器械术语，按用户要求略过','Anabaptist':'较专门的宗派历史名称，按用户要求先略过'})
